function v(t,i=.1){if(t.length<2)return 0;const n=t.some(r=>r<0),f=t.some(r=>r>0);if(!n||!f)return 0;let u=t.length,e=i;for(let r=0;r<50;r++){let l=0,o=0;for(let a=0;a<u;a++){const g=Math.pow(1+e,a);l+=t[a]/g,a>0&&(o-=a*t[a]/(g*(1+e)))}if(Math.abs(l)<1e-4)return e*100;if(Math.abs(o)<1e-10)break;const b=e-l/o;if(Math.abs(b-e)<1e-6)return b*100;if(e=b,e>5||e<-.99)break}return p(t)}function p(t){let i=-.99,n=5;for(let f=0;f<40;f++){let u=(i+n)/2,e=0;for(let r=0;r<t.length;r++)e+=t[r]/Math.pow(1+u,r);if(Math.abs(e)<1e-4)return u*100;e>0?i=u:n=u}return i*100}function M(t){if(t.length===0||t[0]>=0)return 0;let i=t[0];for(let n=1;n<t.length;n++){const f=i;if(i+=t[n],i>=0)return n-1+Math.abs(f)/t[n]}return t.length-1}export{v as a,M as c};
